('10000000-0000-4000-8000-000000000b02', '10000000-0000-4000-8000-000000000003', 'payment', 50000, 'success', 'balance', NULL, '2026-09-30T09:00:00+00:00'),
('10000000-0000-4000-8000-000000000b03', '10000000-0000-4000-8000-000000000003', 'payment', 10000, 'pending', NULL, NULL, '2026-09-30T10:00:00+00:00'),
