SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', 'Buyer', NULL, 100, 0, 0, 0, 0, 100, 'NGN', 'PAID', 'paid', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'receipt', 3, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000003'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, (SELECT COALESCE(jsonb_agg(jsonb_build_object('vat_category_code', ts.vat_category_code, 'vat_rate', ts.vat_rate, 'taxable_amount', ts.taxable_amount, 'tax_amount', ts.tax_amount, 'exemption_reason', ts.exemption_reason) ORDER BY ts.id), '[]'::jsonb) FROM public.order_tax_subtotals AS ts WHERE ts.order_id = '10000000-0000-4000-8000-000000000003'), 2, (SELECT COALESCE(jsonb_agg(jsonb_build_object('amount', t.amount, 'created_at', t.created_at, 'description', t.description, 'metadata', t.metadata) ORDER BY t.id), '[]'::jsonb) FROM public.transactions AS t WHERE t.order_id = '10000000-0000-4000-8000-000000000003' AND t.transaction_type = 'payment' AND t.status IN ('completed', 'success')))->>'status' = 'marked'), 'matching payment history marks dispatch');
